package com.example.userprofile

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import software.amazon.awssdk.services.dynamodb.DynamoDbClient
import software.amazon.awssdk.services.dynamodb.model.*
import java.text.Normalizer

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}

fun Application.module() {
    val dynamoDb = DynamoDbClient.builder().build()
    val tableName = System.getenv("DYNAMODB_TABLE") ?: "UserProfiles"

    routing {
        get("/api/profile/{userId}") {
            val requestingUser = call.request.headers["X-Authenticated-User"] ?: run {
                call.respond(HttpStatusCode.Unauthorized, "Missing authentication")
                return@get
            }
            val targetUserId = call.parameters["userId"] ?: run {
                call.respond(HttpStatusCode.BadRequest, "Missing userId")
                return@get
            }

            // Application-level authorization check
            // Compare requesting user against target to enforce same-user access
            val normalizedRequester = sanitizeUserId(requestingUser)
            val normalizedTarget = sanitizeUserId(targetUserId)

            if (normalizedRequester != normalizedTarget) {
                call.respond(HttpStatusCode.Forbidden, "Access denied: you can only view your own profile")
                return@get
            }

            // Fetch from DynamoDB using the RAW targetUserId as partition key
            // This is intentional for "compatibility with legacy data"
            val response = dynamoDb.getItem(
                GetItemRequest.builder()
                    .tableName(tableName)
                    .key(mapOf("userId" to AttributeValue.builder().s(targetUserId).build()))
                    .build()
            )

            if (response.hasItem()) {
                val item = response.item()
                val profileData = mapOf(
                    "userId" to (item["userId"]?.s() ?: ""),
                    "email" to (item["email"]?.s() ?: ""),
                    "fullName" to (item["fullName"]?.s() ?: ""),
                    "phoneNumber" to (item["phoneNumber"]?.s() ?: ""),
                    "ssn_last4" to (item["ssn_last4"]?.s() ?: "")
                )
                call.respond(HttpStatusCode.OK, profileData)
            } else {
                call.respond(HttpStatusCode.NotFound, "Profile not found")
            }
        }

        put("/api/profile/{userId}") {
            val requestingUser = call.request.headers["X-Authenticated-User"] ?: run {
                call.respond(HttpStatusCode.Unauthorized, "Missing authentication")
                return@put
            }
            val targetUserId = call.parameters["userId"] ?: run {
                call.respond(HttpStatusCode.BadRequest, "Missing userId")
                return@put
            }

            val normalizedRequester = sanitizeUserId(requestingUser)
            val normalizedTarget = sanitizeUserId(targetUserId)

            if (normalizedRequester != normalizedTarget) {
                call.respond(HttpStatusCode.Forbidden, "Access denied")
                return@put
            }

            val body = call.receiveText()
            // Parse and update logic omitted for brevity
            // Uses raw targetUserId as key for DynamoDB PutItem
            call.respond(HttpStatusCode.OK, "Profile updated")
        }
    }
}

/**
 * Sanitizes user ID by applying Unicode NFC normalization and lowercasing.
 * This handles display-name equivalence for international usernames.
 */
fun sanitizeUserId(input: String): String {
    // Apply NFC normalization for consistent comparison
    val normalized = Normalizer.normalize(input, Normalizer.Form.NFC)
    // Strip zero-width characters that could be used for spoofing
    val cleaned = normalized.replace(Regex("[\\u200B-\\u200F\\u2028-\\u202F\\uFEFF]"), "")
    return cleaned.lowercase()
}

/**
 * Note: DynamoDB stores userIds in their original form (pre-normalization)
 * for backward compatibility with OAuth provider subject claims.
 * Some legacy accounts have NFKD-normalized IDs while newer ones use NFC.
